import{_ as a,a0 as l,w as s,s as g,ao as r,I as n,x as o,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"怎樣在Github上託管開源代碼庫 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在Github上託管開源代碼庫 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在Github上託管開源代碼庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在Github上託管開源代碼庫 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 How to Host Open Source Code Repository in github","title":"怎樣在Github上託管開源代碼庫","tag":"201505","desc":""},"relativePath":"201505/20150324 How to Host Open Source Code Repository in github.md","filePath":"[post].md"}'),d={name:"201505/20150324 How to Host Open Source Code Repository in github.md"};function u(h,t,m,b,c,x){const e=l("Link");return s(),g("div",null,[t[16]||(t[16]=r('<h1 id="怎樣在github上託管開源代碼庫" tabindex="-1">怎樣在Github上託管開源代碼庫 <a class="header-anchor" href="#怎樣在github上託管開源代碼庫" aria-label="Permalink to “怎樣在Github上託管開源代碼庫”">​</a></h1><p>大家好，今天我們要學習一下怎樣在github.com提供的倉庫中託管開源軟件源代碼。GitHub是一個基於web的Git倉庫託管服務，提供基於 git 的分佈式版本控制和源代碼管理(SCM)功能，並加入了自身的特點。它給開源項目和私有項目提供了一個互相協作的工作區、代碼預覽和代碼管理功能。不像Git是一個完完全全的命令列工具，GitHub提供了一個基於web的圖形化界面和桌面，也整合了手機操作。GitHub同時提供了私有庫付費計劃和通常用來管理開源軟件項目的免費賬號。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/github-universe.jpg" alt="github universe logo"></p><p>這是一種快速靈活，基於web的託管服務，它使用方便，管理分佈式版本控制系統也是相當容易，任何人都能將他們的軟件源代碼託管到 github，讓全球各地數以百萬計的人可以使用它、參與貢獻、共享它、進行問題跟蹤以及更多的用途。這裏有一些簡單快速地託管軟件源代碼的方法。</p><h3 id="_1-創建一個新的github賬號" tabindex="-1">1. 創建一個新的Github賬號 <a class="header-anchor" href="#_1-創建一個新的github賬號" aria-label="Permalink to “1. 創建一個新的Github賬號”">​</a></h3>',5)),n("p",null,[t[1]||(t[1]=o("首先，打開你最喜歡的瀏覽器並訪問",-1)),i(e,{href:"http://github.com/"},{default:p(()=>[...t[0]||(t[0]=[o("github",-1)])]),_:1}),t[2]||(t[2]=o("，首頁頁面如下所示。",-1))]),t[17]||(t[17]=r(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/github-homepage.png" alt="Github Homepage"></p><p>現在，首頁打開之後，請填寫一個新的github賬號用於註冊。</p><p>輸入註冊所需的有效信息之後，你會被轉到計劃選擇的步驟。在這個頁面上有5種計劃，我們可以根據需要來選擇，這裏我們要選擇免費計劃。所以，我們點擊選擇Free計劃並完成註冊。如果我們接下去還打算創建一個組織，那我們需要勾選“Help me setup an organization next”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/choosing-plan.png" alt="choosing plan"></p><h3 id="_2-創建一個新的庫" tabindex="-1">2. 創建一個新的庫 <a class="header-anchor" href="#_2-創建一個新的庫" aria-label="Permalink to “2. 創建一個新的庫”">​</a></h3><p>成功註冊新賬號或登錄上Github之後，我們需要創建一個新的庫來開始我們的征程。</p><p>點擊位於頂部靠右賬號id旁邊的<strong>(+)</strong>按鈕，然後點擊“New Repository”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/create-new-repository.png" alt="Add new repository"></p><p>點擊創建一個新的庫之後，我們進入了填寫所需信息的頁面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/adding-information-repository.png" alt="adding repository information"></p><p>填寫好信息之後，我們點擊綠色的“Create repository”按鈕。</p><p>這些步驟都做完之後，我們將看到類似於下面這張圖的頁面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/repository-github.png" alt="repository github"></p><h3 id="_3-上傳一個已有項目" tabindex="-1">3. 上傳一個已有項目 <a class="header-anchor" href="#_3-上傳一個已有項目" aria-label="Permalink to “3. 上傳一個已有項目”">​</a></h3><p>如果我們想在Github上分享我們的項目，我們自然要把代碼推上我們創建的庫中。想要這樣的話，我們首先要在我們的Linux機器上安裝git。如果我在機器上運行的是Ubuntu 14.04 LTS，我需要運行<strong>apt</strong>工具來安裝它。</p><pre><code>$ sudo apt-get install git
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/install-git.png" alt="installing git"></p><p>現在git已經準備就緒，我們要上傳代碼了。</p><p><strong>注意</strong>：為了避免錯誤，不要在初始化的新庫中包含<strong>README</strong>、license或gitignore等文件，你可以在項目推送到Github上之後再添加它們。</p><p>在終端上，我們需要切換當前工作目錄為你的本地項目的目錄，然後將其初始化為Git庫。</p><pre><code>$ git init
</code></pre><p>接着我們添加新的本地庫裏中的文件，作為我們的首次提交內容。</p><pre><code>$ git add .
</code></pre><p>現在我們就提交我們在本地庫所添加的文件。</p><pre><code>$ git commit -m &#39;First commit&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/git-commit.png" alt="git commit"></p><p>在終端上，添加遠程庫的URL地址，以便我們的本地庫推送到遠程。</p><pre><code>$ git remote add origin 遠程庫的URL
$ git remote -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/adding-remote-url.png" alt="adding remote url"></p><p>注意：請確保將上述“遠程庫的URL”替換成了你自己的遠程庫的URL。</p><p>現在，要將我們的本地庫的改變推送至GitHub的版本庫中，我們需要運行以下命令，並且輸入所需的用户名和密碼。</p><pre><code>$ git push origin master
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pushing-repo.png" alt="pushing repo"></p><h3 id="克隆一個庫" tabindex="-1">克隆一個庫 <a class="header-anchor" href="#克隆一個庫" aria-label="Permalink to “克隆一個庫”">​</a></h3><p>如果我們想用一條簡單地命令從github上下載代碼庫至本機上，我們可以用git clone命令，該命令將會從遠程庫中克隆最新的目錄。</p><pre><code>$ git clone https://github.com/aruntechgeek/linspeed.git
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/cloning-repo.png" alt="cloning repo"></p><p>請把以上這條URL地址更改成你想要克隆的地址。</p><h3 id="推送改動" tabindex="-1">推送改動 <a class="header-anchor" href="#推送改動" aria-label="Permalink to “推送改動”">​</a></h3><p>如果我們對我們的代碼做了更改並想把它們推送至我們的遠程庫中，我們應該在該目錄下運行以下命令。</p><pre><code>$ git add .
$ git commit -m &quot;Updating&quot;
$ git push
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>啊哈！我們已經成功地將我們的項目源代碼託管到Github的庫中了。Github是快速靈活的基於web的託管服務，分佈式版本控制系統使用起來方便容易。數百萬個非常棒的開源項目駐紮在github上。所以，如果你有任何問題、建議或反饋，請在評論中告訴我們。謝謝大家！好好享受吧 😃</p><hr>`,44)),n("p",null,[t[4]||(t[4]=o("via: ",-1)),i(e,{href:"http://linoxide.com/usr-mgmt/host-open-source-code-repository-github/"},{default:p(()=>[...t[3]||(t[3]=[o("http://linoxide.com/usr-mgmt/host-open-source-code-repository-github/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=o("作者：",-1)),i(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...t[5]||(t[5]=[o("Arun Pyasi",-1)])]),_:1}),t[9]||(t[9]=o(" 譯者：",-1)),i(e,{href:"https://github.com/ZTinoZ"},{default:p(()=>[...t[6]||(t[6]=[o("ZTinoZ",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[o("Linux中國",-1)])]),_:1}),t[15]||(t[15]=o(" 榮譽推出",-1))])])}const C=a(d,[["render",u]]);export{w as __pageData,C as default};
